param()
$ErrorActionPreference='Continue';$Base=Join-Path $env:LOCALAPPDATA 'HomeDesignAutomationV7';$UserData=Join-Path $Base 'ChromeUserData';$CftRoot=Join-Path $Base 'ChromeForTesting';$NotebookExt=Join-Path $Base 'Extension\NotebookLM-WebApp-Bridge';$NotebookFront='https://notebooklm-webapp-bridge.vercel.app/'
function NormalRoots{try{@(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'" -ErrorAction SilentlyContinue|Where-Object{(-not $_.CommandLine -or -not([string]$_.CommandLine).Contains($UserData)) -and (-not $_.CommandLine -or ([string]$_.CommandLine)-notmatch '(?i)(^|\s)--type=')}|ForEach-Object{[int]$_.ProcessId})}catch{@()}}
$normalBefore=@(NormalRoots);$killed=@();try{foreach($p in @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue)){$cmd=[string]$p.CommandLine;if(!$cmd){continue};if($cmd -match '(?i)(RunFlowBridgeConnectSmoke\.ps1|RunFlowBridgeWorkspaceProbeV3\.ps1|flow-bridge-deep-probe-.*\.mjs|flow-v3-.*\.mjs)'){try{& taskkill.exe /PID ([int]$p.ProcessId) /T /F 2>$null|Out-Null;$killed+=[ordered]@{pid=[int]$p.ProcessId;name=[string]$p.Name;commandLine=$cmd}}catch{}}}}catch{}
try{foreach($p in @(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'" -ErrorAction SilentlyContinue|Where-Object{$_.CommandLine -and ([string]$_.CommandLine).Contains($UserData)})){try{& taskkill.exe /PID ([int]$p.ProcessId) /T /F 2>$null|Out-Null;$killed+=[ordered]@{pid=[int]$p.ProcessId;name='chrome.exe';dedicated=$true}}catch{}}}catch{};Start-Sleep -Seconds 2
$chrome=Get-ChildItem -LiteralPath $CftRoot -Recurse -Filter chrome.exe -File -ErrorAction SilentlyContinue|Sort-Object FullName -Descending|Select-Object -First 1;$restored=$false;if($chrome){$args=@("--user-data-dir=$UserData",'--profile-directory=Default','--new-window','--no-first-run','--no-default-browser-check','--disable-session-crashed-bubble');if(Test-Path -LiteralPath (Join-Path $NotebookExt 'manifest.json') -PathType Leaf){$args+=("--load-extension=$NotebookExt")};$args+=$NotebookFront;try{Start-Process -FilePath $chrome.FullName -ArgumentList $args -WorkingDirectory $chrome.Directory.FullName|Out-Null;Start-Sleep -Seconds 2;$restored=$true}catch{}}
$normalAfter=@(NormalRoots);$missing=@($normalBefore|Where-Object{$normalAfter -notcontains $_});[ordered]@{ok=($missing.Count -eq 0 -and $restored);action='RECOVER_STALE_FLOW_PROBE';killed=$killed;notebookDedicatedRestored=[bool]$restored;normalChromeBefore=$normalBefore;normalChromeAfter=$normalAfter;normalChromeMissingRootPids=$missing;normalChromeUntouched=($missing.Count -eq 0);generateClicked=$false;creditSpend=$false;oauthChanged=$false;chromeSettingsChanged=$false;at=(Get-Date).ToString('o')}|ConvertTo-Json -Depth 20 -Compress;exit 0
